commands:
# Run in 64-bit PowerShell

 # Kill Discord and wait
 Get-Process -Name Discord -ErrorAction SilentlyContinue | Stop-Process -Force
 Start-Sleep -Seconds 5

 # Paths
 $discordRoot = Join-Path $env:LOCALAPPDATA 'Discord'
 $appDir = Get-ChildItem -Path (Join-Path $discordRoot 'app*') -Directory -ErrorAction SilentlyContinue |
  Sort-Object Name -Descending | Select-Object -First 1

 # Cleanup updater artifacts
 Remove-Item "$discordRoot\Discord_updater*" -Force -ErrorAction SilentlyContinue
 Remove-Item "$discordRoot\SquirrelSetup*" -Force -ErrorAction SilentlyContinue

 if ($appDir) {
  # Delete selected files and folders
  Remove-Item (Join-Path $appDir.FullName 'app.ico') -Force -ErrorAction SilentlyContinue
  Remove-Item (Join-Path $appDir.FullName 'debug.log') -Force -ErrorAction SilentlyContinue
  Remove-Item (Join-Path $appDir.FullName 'swiftshader') -Recurse -Force -ErrorAction SilentlyContinue

  # Languages: keep en-US only
  $loc = Join-Path $appDir.FullName 'locales'
  if (Test-Path (Join-Path $loc 'en-US.pak')) {
  Copy-Item (Join-Path $loc 'en-US.pak') $discordRoot -Force -ErrorAction SilentlyContinue
  }
  if (Test-Path $loc) { Remove-Item $loc -Recurse -Force -ErrorAction SilentlyContinue }
  New-Item -ItemType Directory -Path $loc -Force 
  if (Test-Path (Join-Path $discordRoot 'en-US.pak')) {
  Move-Item (Join-Path $discordRoot 'en-US.pak') $loc -Force
  }

  # Modules cleanup
  $modulesDir = Join-Path $appDir.FullName 'modules'
  if (Test-Path $modulesDir) {
  $mods = @(
  'discord_cloudsync-1','discord_dispatch-1','discord_erlpack-1',
  'discord_game_utils-1','discord_game_utils-2',
  'discord_media-1','discord_media-2',
  'discord_spellcheck-1','discord_hook-1','discord_hook-2'
  )
  foreach ($m in $mods) {
  $p = Join-Path $modulesDir $m
  if (Test-Path $p) {
  Remove-Item $p -Recurse -Force
  Write-Output (" Removed {0}" -f $m)
  }
  }
  }
 } else {
  Write-Output "Discord app folder not found under $discordRoot"
 }
